input.query:
WITH ['/pulsar-broker-4.2.5.jar','/pulsar-broker-common-4.2.5.jar','/pulsar-client-original-4.2.5.jar','/pulsar-client-api-4.2.5.jar','/pulsar-common-4.2.5.jar','/pulsar-metadata-4.2.5.jar','/managed-ledger-4.2.5.jar'] AS jars
MATCH (s:Type)-[:DEPENDS_ON]->(t:Type) WHERE t.fqn STARTS WITH 'org.apache.pulsar.' AND NOT t:Inner AND s.fqn STARTS WITH 'org.apache.pulsar.' AND s.fqn<>t.fqn AND NOT s.fqn STARTS WITH t.fqn+'$'
AND EXISTS { MATCH (a:Artifact)-[:CONTAINS]->(s) WHERE a.fileName IN jars }
AND EXISTS { MATCH (b:Artifact)-[:CONTAINS]->(t) WHERE b.fileName IN jars }
RETURN t.fqn AS fqn, count(DISTINCT s.fqn) AS c ORDER BY c DESC LIMIT 12

