input.query:
WITH ['/pulsar-broker-4.2.5.jar','/pulsar-broker-common-4.2.5.jar','/pulsar-client-original-4.2.5.jar','/pulsar-client-api-4.2.5.jar','/pulsar-common-4.2.5.jar','/pulsar-metadata-4.2.5.jar','/managed-ledger-4.2.5.jar'] AS jars
MATCH (:Artifact)-[:CONTAINS]->(r:Type) WHERE r.fqn STARTS WITH 'org.apache.pulsar.' AND NOT r:Inner AND EXISTS { MATCH (b:Artifact)-[:CONTAINS]->(r) WHERE b.fileName IN jars }
WITH jars, collect(DISTINCT r.fqn) AS targets
